import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadinbench.Application;
import com.vaadinbench.ItemsView;

@SpringBootTest(classes = Application.class)
class ItemsViewTest extends SpringBrowserlessTest {

    @Test
    void addItem_appendsItemAndUpdatesCount() {
        navigate(ItemsView.class);

        test(itemField()).setValue("Milk");
        test(button("Add")).click();

        Assertions.assertEquals(List.of("Milk"), itemTexts());
        Assertions.assertEquals("", itemField().getValue());
        Assertions.assertEquals("Items: 1", countText());
    }

    @Test
    void addBlankItem_addsNothingAndMarksFieldInvalid() {
        navigate(ItemsView.class);

        test(itemField()).setValue("   ");
        test(button("Add")).click();

        Assertions.assertTrue(itemField().isInvalid());
        Assertions.assertTrue(itemTexts().isEmpty());
        Assertions.assertEquals("Items: 0", countText());
    }

    @Test
    void addSameTextTwice_createsTwoItems() {
        navigate(ItemsView.class);

        test(itemField()).setValue("Milk");
        test(button("Add")).click();
        test(itemField()).setValue("Milk");
        test(button("Add")).click();

        Assertions.assertEquals(List.of("Milk", "Milk"), itemTexts());
        Assertions.assertEquals("Items: 2", countText());
    }

    @Test
    void clear_removesAllItemsAndItemsCanBeAddedAgain() {
        navigate(ItemsView.class);

        test(itemField()).setValue("Milk");
        test(button("Add")).click();
        test(button("Clear")).click();

        Assertions.assertTrue(itemTexts().isEmpty());
        Assertions.assertEquals("Items: 0", countText());

        test(itemField()).setValue("Eggs");
        test(button("Add")).click();

        Assertions.assertEquals(List.of("Eggs"), itemTexts());
        Assertions.assertEquals("Items: 1", countText());
    }

    private TextField itemField() {
        return findInView(TextField.class).withLabel("Item").single();
    }

    private Button button(String text) {
        return findInView(Button.class).withText(text).single();
    }

    private List<String> itemTexts() {
        return findInView(ListItem.class).all().stream().map(ListItem::getText).toList();
    }

    private String countText() {
        return findInView(Span.class).withText("Items: " + "").all().isEmpty()
                ? findInView(Span.class).all().stream().map(Span::getText)
                        .filter(t -> t.startsWith("Items: ")).findFirst().orElseThrow()
                : null;
    }
}
